      var isWaitStep = step && (step.action === 'grant' || step.action === 'confirm')
      if (C.autoPlay === 'full') return resolve()
      if (C.autoPlay === 'once' && !(step && step.action === 'grant')) return resolve()
      if (C.autoPlay === 'off' && !isWaitStep) return resolve()
